        int attack = 15;
        int bonus = 10;
        System.out.println(0);
    }
}

lessons.solution:
public class Main {
    public static void main(String[] args) {
        int attack = 15;
        int bonus = 10;
        System.out.println(attack + bonus);
    }
}

